import random

class GameBoard:
    def __init__(self):
        self.board = [[0] * 4 for _ in range(4)]
        self.score = 0
        self.highest_tile = 0
        self.initialize_board()

    def initialize_board(self):
        self.add_random_tile()
        self.add_random_tile()

    def add_random_tile(self):
        empty_cells = [(i, j) for i in range(4) for j in range(4) if self.board[i][j] == 0]
        if empty_cells:
            i, j = random.choice(empty_cells)
            self.board[i][j] = 2 if random.random() < 0.9 else 4

    def is_game_over(self):
        for i in range(4):
            for j in range(4):
                if self.board[i][j] == 0:
                    return False
                if (i > 0 and self.board[i][j] == self.board[i-1][j]) or \
                   (i < 3 and self.board[i][j] == self.board[i+1][j]) or \
                   (j > 0 and self.board[i][j] == self.board[i][j-1]) or \
                   (j < 3 and self.board[i][j] == self.board[i][j+1]):
                    return False
        return True

    def move(self, direction):
        if direction == 'w':
            for j in range(4):
                self._move_column(j, up=True)
        elif direction == 'a':
            for i in range(4):
                self._move_row(i, left=True)
        elif direction == 's':
            for j in range(4):
                self._move_column(j, up=False)
        elif direction == 'd':
            for i in range(4):
                self._move_row(i, left=False)

    def _move_column(self, j, up=True):
        if up:
            for i in range(1, 4):
                if self.board[i][j] != 0:
                    for k in range(i, 0, -1):
                        if self.board[k-1][j] == 0:
                            self.board[k-1][j], self.board[k][j] = self.board[k][j], self.board[k-1][j]
                        elif self.board[k-1][j] == self.board[k][j]:
                            self.board[k-1][j] *= 2
                            self.board[k][j] = 0
                            self.score += self.board[k-1][j]
                            if self.board[k-1][j] > self.highest_tile:
                                self.highest_tile = self.board[k-1][j]
                            break
        else:
            for i in range(2, -1, -1):
                if self.board[i][j] != 0:
                    for k in range(i, 3):
                        if self.board[k+1][j] == 0:
                            self.board[k+1][j], self.board[k][j] = self.board[k][j], self.board[k+1][j]
                        elif self.board[k+1][j] == self.board[k][j]:
                            self.board[k+1][j] *= 2
                            self.board[k][j] = 0
                            self.score += self.board[k+1][j]
                            if self.board[k+1][j] > self.highest_tile:
                                self.highest_tile = self.board[k+1][j]
                            break

    def _move_row(self, i, left=True):
        if left:
            for j in range(1, 4):
                if self.board[i][j] != 0:
                    for k in range(j, 0, -1):
                        if self.board[i][k-1] == 0:
                            self.board[i][k-1], self.board[i][k] = self.board[i][k], self.board[i][k-1]
                        elif self.board[i][k-1] == self.board[i][k]:
                            self.board[i][k-1] *= 2
                            self.board[i][k] = 0
                            self.score += self.board[i][k-1]
                            if self.board[i][k-1] > self.highest_tile:
                                self.highest_tile = self.board[i][k-1]
                            break
        else:
            for j in range(2, -1, -1):
                if self.board[i][j] != 0:
                    for k in range(j, 3):
                        if self.board[i][k+1] == 0:
                            self.board[i][k+1], self.board[i][k] = self.board[i][k], self.board[i][k+1]
                        elif self.board[i][k+1] == self.board[i][k]:
                            self.board[i][k+1] *= 2
                            self.board[i][k] = 0
                            self.score += self.board[i][k+1]
                            if self.board[i][k+1] > self.highest_tile:
                                self.highest_tile = self.board[i][k+1]
                            break

    def merge_tiles(self):
        for i in range(4):
            for j in range(4):
                if self.board[i][j] != 0:
                    if (i > 0 and self.board[i][j] == self.board[i-1][j]) or \
                       (i < 3 and self.board[i][j] == self.board[i+1][j]) or \
                       (j > 0 and self.board[i][j] == self.board[i][j-1]) or \
                       (j < 3 and self.board[i][j] == self.board[i][j+1]):
                        self.board[i][j] *= 2
                        self.score += self.board[i][j]
                        if self.board[i][j] > self.highest_tile:
                            self.highest_tile = self.board[i][j]

    def get_current_score(self):
        return self.score

    def get_highest_tile(self):
        return self.highest_tile
